1	"use server";
2	
3	// Server actions behind the "card on file" section of the customer billing page.
4	//
5	// The whole flow is redirect-based (Stripe hosted Checkout in `mode: "setup"`),
6	// because no Stripe Elements / Stripe.js integration exists in this codebase and
7	// no publishable key is plumbed to the browser. That means there is a moment where
8	// the card exists at Stripe and not here, which is exactly the shape of the
9	// fulfilment bug that cost a customer their server once already — see
10	// `adoptUnclaimedCards` in `lib/stripe-cards.ts` for the backstop.
11	//
12	// ROUTE NOTE: `app/api/stripe/**` is owned elsewhere, so the return leg is NOT an
13	// API route. Stripe redirects to `/dashboard/billing?card_setup=<session_id>` and
14	// a small client component calls `finalizeCardSetup` below. If a route is wanted
15	// later, the natural one is `GET /api/stripe/setup-return?session_id=…` calling
16	// `saveCardFromSetupSession(sessionId, currentUser().id)` and redirecting to
17	// `/dashboard/billing?card=saved`.
18	
19	import { revalidatePath } from "next/cache";
20	import { db } from "./db";
21	import { requireUser, assertNotImpersonating } from "./auth";
22	import { stripeConfigured } from "./stripe";
23	import { walletSplit } from "./wallet-split";
24	import { dedicatedIpMonthlyCents } from "./dedicated-ip";
25	import { extraDiskPerGbCents } from "./disk-expand";
26	import {
27	  CARD_REMOVED,
28	  CARD_SETUP_STARTED,
29	  cardDisplayLabel,
30	  createCardSetupSession,
31	  createOutstandingCheckout,
32	  detachSavedCard,
33	  renewalCharge,
34	  retryDunningNow,
35	  saveCardFromSetupSession,
36	} from "./stripe-cards";
37	
38	/**
39	 * Begin saving a card. Returns the hosted Checkout URL for the browser to follow.
40	 *
41	 * The `card.setup_started` audit row is not just bookkeeping: it is the evidence
42	 * `adoptUnclaimedCards` requires before it will adopt a card that is attached at
43	 * Stripe but was never confirmed here, which is what keeps a REMOVED card from
44	 * being silently resurrected.
45	 */
46	export async function startCardSetup(): Promise<{ url?: string; error?: string }> {
47	  // An admin impersonating a customer must not be able to put a card on their
48	  // account — the same reasoning that blocks impersonated wallet spend.
49	  await assertNotImpersonating();
50	  const user = await requireUser();
51	  if (!stripeConfigured()) {
52	    return { error: "Card payments aren't configured on this installation yet." };
53	  }
54	  try {
55	    const url = await createCardSetupSession(user);
56	    if (!url) return { error: "Stripe didn't return a setup link. Please try again." };
57	    await db.auditLog.create({ data: { userId: user.id, action: CARD_SETUP_STARTED } });
58	    return { url };
59	  } catch (e) {
60	    console.error("[payment-method] setup session failed", e);
61	    return { error: "We couldn't start card setup just now. Please try again in a moment." };
62	  }
63	}
64	
65	/**
66	 * Finish saving a card after Stripe redirects back.
67	 *
68	 * Safe to call repeatedly with the same session id — it re-reads the same payment
69	 * method from Stripe and writes the same columns, so a refreshed tab is a no-op
70	 * rather than a second card.
71	 */
72	export async function finalizeCardSetup(
73	  sessionId: string,
74	): Promise<{ ok?: boolean; label?: string; error?: string }> {
75	  await assertNotImpersonating();
76	  const user = await requireUser();
77	  if (!sessionId) return { error: "Missing card setup reference." };
78	
79	  const res = await saveCardFromSetupSession(sessionId, user.id);
80	  if (res.error || !res.card) return { error: res.error ?? "The card wasn't saved." };
81	
82	  const label = cardDisplayLabel(res.card) ?? "Card saved";
83	  await db.auditLog.create({ data: { userId: user.id, action: "card.saved", detail: label } });
84	  // Anyone mid-dunning was told we'd charge a new card straight away; make it true.
85	  const requeued = await retryDunningNow(user.id);
86	  if (requeued > 0) {
87	    await db.notification.create({
88	      data: {
89	        userId: user.id,
90	        title: "Card saved — we'll retry your renewal shortly",
91	        body: `We'll charge ${label} for the outstanding renewal within the next few minutes. Nothing is suspended.`,
92	        href: "/dashboard/billing",
93	      },
94	    });
95	  }
96	  revalidatePath("/dashboard/billing");
97	  return { ok: true, label };
98	}
99	
100	/** Remove the card on file (detaches at Stripe first — see `detachSavedCard`). */
101	export async function removeSavedCard(): Promise<{ ok?: boolean; error?: string }> {
102	  await assertNotImpersonating();
103	  const user = await requireUser();
104	  const label = cardDisplayLabel({
105	    brand: user.cardBrand,
106	    last4: user.cardLast4,
107	    expMonth: user.cardExpMonth,
108	    expYear: user.cardExpYear,
109	  });
110	  const res = await detachSavedCard(user.id);
111	  if (res.error) return { error: res.error };
112	  await db.auditLog.create({
113	    data: { userId: user.id, action: CARD_REMOVED, detail: label ?? "card on file" },
114	  });
115	  revalidatePath("/dashboard/billing");
116	  return { ok: true };
117	}
118	
119	/**
120	 * Mint a FRESH hosted-Checkout link for a server's outstanding renewal balance.
121	 *
122	 * A link is minted on demand rather than reusing the stored `dunningPayUrl`
123	 * because Stripe Checkout sessions expire within 24 hours while the dunning
124	 * sequence runs for six days — surfacing the stored link in the portal would show
125	 * an expired Stripe page to a customer trying to pay us.
126	 */
127	export async function settleOutstanding(
128	  serverId: string,
129	): Promise<{ url?: string; error?: string; covered?: boolean }> {
130	  const user = await requireUser();
131	  if (!stripeConfigured()) {
132	    return { error: "Card payments aren't configured — add funds to your wallet instead." };
133	  }
134	  const server = await db.server.findUnique({
135	    where: { id: serverId },
136	    include: { plan: true, gamePlan: true, dedicatedIp: true },
137	  });
138	  if (!server) return { error: "Server not found." };
139	  if (server.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden" };
140	  if (server.isFree || !server.expiresAt) return { error: "This server has nothing outstanding." };
141	
142	  const charge = renewalCharge(server, {
143	    ipMonthlyCents: await dedicatedIpMonthlyCents(),
144	    extraDiskPerGbCents: await extraDiskPerGbCents(),
145	  });
146	  // Wallet credit first, card for the remainder — the same split the sweep will
147	  // apply, so the quote here and the charge there can never disagree.
148	  const split = walletSplit({
149	    dueCents: charge.totalCents,
150	    balanceCents: user.balanceCents,
151	    useWallet: true,
152	  });
153	  if (split.cardCents === 0) {
154	    return {
155	      covered: true,
156	      error: "Your wallet already covers this renewal — it completes automatically within a few minutes.",
157	    };
158	  }
159	
160	  const url = await createOutstandingCheckout({
161	    user,
162	    amountCents: split.cardCents,
163	    hostname: server.hostname,
164	    serverId: server.id,
165	  });
166	  if (!url) return { error: "We couldn't start checkout just now. Please try again in a moment." };
167	  // Keep the stored link current for the dunning emails and admin visibility.
168	  await db.server.update({ where: { id: server.id }, data: { dunningPayUrl: url } });
169	  return { url };
170	}
