482	async function findChargeByMarker(
483	  customerId: string,
484	  marker: string,
485	): Promise<Stripe.PaymentIntent | null> {
486	  // 25 is generous: renewals are monthly and this is scoped to one customer, so a
487	  // charge made minutes or days ago is always inside this window.
488	  const list = await stripe().paymentIntents.list({ customer: customerId, limit: 25 });
489	  const mine = list.data.filter((pi) => pi.metadata?.nxeonChargeKey === marker);
490	  return (
491	    mine.find((pi) => pi.status === "succeeded") ??
492	    mine.find((pi) => pi.status === "requires_action") ??
493	    mine.find((pi) => pi.status === "processing") ??
494	    null
495	  );
