522	  // the belt-and-braces check so a future caller can't send a rejectable amount.
523	  if (amountCents < STRIPE_MIN_CENTS) {
524	    return { ok: false, kind: "unavailable", message: `Below Stripe minimum (${STRIPE_MIN_CENTS}c)` };
525	  }
526	
527	  // Guard 1: did we already charge for this purpose?
528	  try {
529	    const existing = await findChargeByMarker(user.stripeCustomerId, marker);
530	    if (existing?.status === "succeeded") {
531	      return {
532	        ok: true,
533	        paymentIntentId: existing.id,
534	        amountCents: existing.amount_received || existing.amount,
535	        replayed: true,
536	      };
537	    }
538	    if (existing?.status === "requires_action") {
539	      // A 3-D Secure wall does not move: retrying the SAME card off-session hits it
540	      // again, so reuse the existing intent (and its link) rather than piling up a
541	      // new challenge every retry. A DIFFERENT card is a different story — if the
542	      // customer has since saved one, cancel the stale challenge and really try it,
543	      // otherwise saving a new card would silently change nothing.
544	      const pendingPm =
545	        typeof existing.payment_method === "string"
546	          ? existing.payment_method
547	          : (existing.payment_method?.id ?? null);
548	      if (pendingPm === user.stripePaymentMethodId) {
549	        return {
550	          ok: false,
551	          kind: "requires_action",
552	          paymentIntentId: existing.id,
553	          message: "Awaiting bank confirmation",
554	        };
555	      }
556	      await cancelIfUnconfirmed(existing.id);
