599	/**
600	 * Split a charge failure into the three cases that deserve different treatment:
601	 * the bank wants the customer to confirm, the bank said no, or nothing about the
602	 * customer went wrong at all.
603	 *
604	 * The default is `transient` on purpose. A misclassified transient error costs us
605	 * a delayed renewal; a misclassified decline costs a paid-up customer their
606	 * server. Unknown always resolves to the direction that cannot suspend anyone.
607	 */
608	function classifyChargeError(e: unknown): OffSessionResult {
609	  const err = asStripeError(e);
610	  const message = String(err?.message ?? (e as Error)?.message ?? e).slice(0, 300);
611	  if (!err) return { ok: false, kind: "transient", message };
612	
613	  // 3-D Secure surfaces as a card error with this code, with the PI attached.
614	  if (err.code === "authentication_required" || err.payment_intent?.status === "requires_action") {
615	    return {
616	      ok: false,
617	      kind: "requires_action",
618	      paymentIntentId: err.payment_intent?.id ?? null,
619	      message,
620	    };
621	  }
622	  if (err.rawType === "card_error") {
623	    return { ok: false, kind: "declined", message, code: err.decline_code ?? err.code };
624	  }
625	  // The saved method vanished at Stripe (detached elsewhere, customer deleted).
626	  // Not a decline — there is nothing to retry until a new card is saved.
627	  if (err.rawType === "invalid_request_error" && err.code === "resource_missing") {
628	    return { ok: false, kind: "unavailable", message };
629	  }
630	  return { ok: false, kind: "transient", message };
631	}
