1056	 * Honour the customer's own "keep my wallet topped up" preference.
1057	 *
1058	 * This is opt-in and customer-configured (`autoRechargeEnabled` /
1059	 * `autoRechargeThresholdCents` / `autoRechargeAmountCents`), and it is the only
1060	 * charge in this file that is NOT tied to a renewal — so unlike the renewal leg it
1061	 * DOES get its own invoice, because it is the whole payment rather than one part
1062	 * of a larger one.
1063	 *
1064	 * `autoRechargeMarker` is scoped to the account and the CALENDAR DAY, which caps
1065	 * this at one top-up per account per day no matter how many times the sweep runs
1066	 * or how fast the customer spends. Combined with the UNIQUE index on
1067	 * `WalletTransaction.stripePaymentIntentId`, a replayed capture credits once and
1068	 * emails once.
1069	 */
1070	async function autoRechargeSweep(now: Date): Promise<void> {
1071	  if (!stripeConfigured()) return;
1072	  const users = await db.user.findMany({
1073	    where: {
1074	      autoRechargeEnabled: true,
1075	      suspended: false,
1076	      stripeCustomerId: { not: null },
1077	      stripePaymentMethodId: { not: null },
1078	    },
1079	  });
1080	
1081	  for (const user of users) {
1082	    const threshold = user.autoRechargeThresholdCents ?? 0;
1083	    const amount = user.autoRechargeAmountCents ?? 0;
1084	    // A threshold of 0 means "never", and an amount below the floor the customer's
1085	    // own settings form enforces is a stale/hand-edited row — charging on either
1086	    // would be taking money the customer did not ask for.
1087	    if (threshold <= 0 || amount < AUTO_RECHARGE_MIN_CENTS) continue;
1088	    if (user.balanceCents >= threshold) continue;
1089	
1090	    const day = now.toISOString().slice(0, 10);
1091	    const marker = autoRechargeMarker(user.id, now);
1092	    let result: OffSessionResult;
1093	    try {
1094	      result = await chargeSavedCardOffSession({
1095	        user,
1096	        amountCents: amount,
1097	        description: `${AUTO_RECHARGE_DESC} — Nxeon wallet`,
1098	        marker,
1099	        idempotencyKey: `nxeon_autorecharge_${user.id}_${day}_${amount}`,
1100	        metadata: { nxeonKind: "auto_recharge" },
1101	      });
1102	    } catch (e) {
1103	      // One wedged account must not stop the others from topping up.
1104	      console.error(`[billing] auto-recharge error for ${user.email}`, e);
1105	      continue;
1106	    }
1107	
1108	    if (result.ok) {
1109	      const credited = await creditOffSessionCharge({
1110	        userId: user.id,
1111	        amountCents: result.amountCents,
1112	        description: `${AUTO_RECHARGE_DESC} (${savedCardLabel(user) ?? "saved card"})`,
1113	        paymentIntentId: result.paymentIntentId,
1114	        // This charge IS the whole payment, so it gets its own PAID invoice — in
1115	        // the same guarded write, so the invoice cannot outlive a rolled-back credit.
1116	        invoiceDescription: AUTO_RECHARGE_DESC,
1117	      });
1118	      if (!credited) continue; // already credited today — nothing new to announce
1119	      await mail(
1120	        user.email,
1121	        user.id,
1122	        emails.paymentReceipt(fmtUsd(result.amountCents), AUTO_RECHARGE_DESC, user.cardLast4 ?? ""),
