// `worker/billing.ts` owns the dunning POLICY, and every constant that shapes it
// (`retryDayFor`, `CARD_SUSPEND_DAY`, `DUNNING_EXHAUSTED`, `SUSPEND_SLIP_CAP_DAYS`,
// `suspendDueAt`) is module-private there. The portal cannot import them: that file
// pulls in the provisioning worker's whole world — Proxmox, nodemailer, the job
// queue — and none of it belongs in a page bundle.
//
// So the DAY ARITHMETIC is duplicated here, deliberately, and each constant is
// named exactly as the worker names it so a change to the schedule is greppable.
// This is the same trade `lib/actions-settings.ts` already makes for
// MIN_TERMINATE_DAYS, and it is guarded the same way: `test/payment-method-ui.test.ts`
// reads worker/billing.ts and fails the moment the two disagree.
//
// DUNNING_RETRY_ATTEMPTS itself is IMPORTED rather than copied. It is the one number
// the dunning emails subtract from ("we'll try 2 more times"), and a second copy of
// it is precisely how that promise starts outliving the retries that back it.
//
// Plain server module. Everything below is pure arithmetic on the columns the worker
// writes, so a server component can compute the view once and hand plain data to a
// client component — no clock or database access hides in here.

import { DUNNING_RETRY_ATTEMPTS } from "./mailer";

export { DUNNING_RETRY_ATTEMPTS };

const DAY = 86_400_000;

/** Mirrors `const retryDayFor = (retry: number) => 2 * retry - 1;` in worker/billing.ts. */
export const retryDayFor = (retry: number) => 2 * retry - 1;
/** Mirrors `const CARD_SUSPEND_DAY = LAST_RETRY_DAY + 1;` — one clear day after the final notice. */
const SUSPEND_DAYS_AFTER_LAST_RETRY = 1;
/** Mirrors `const SUSPEND_SLIP_CAP_DAYS = 4;` in worker/billing.ts. */
export const SUSPEND_SLIP_CAP_DAYS = 4;

/** Days past expiry on which the worker retries the saved card. */
export const RETRY_DAYS: number[] = Array.from({ length: DUNNING_RETRY_ATTEMPTS }, (_, i) =>
  retryDayFor(i + 1),
);
/** Days past expiry of the LAST automatic retry. */
export const LAST_RETRY_DAY = retryDayFor(DUNNING_RETRY_ATTEMPTS);
/** Days past expiry when a card customer's server pauses, if nothing has been paid. */
export const CARD_SUSPEND_DAY = LAST_RETRY_DAY + SUSPEND_DAYS_AFTER_LAST_RETRY;
/**
 * `Server.dunningStage` once every automatic attempt is spent: the attempt made on
 * expiry day itself, plus one per retry. Mirrors
 * `const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS + 1;`.
 */
export const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS + 1;

/** The columns `worker/billing.ts` reads to decide what happens to an overdue server. */
export type DunningInput = {
  expiresAt: Date | null;
  dunningStage: number;
  dunningNextAt: Date | null;
};

export type DunningView = {
  /** Whether this account can actually be auto-charged — changes the whole ladder. */
  hasCard: boolean;
  /** True once at least one automatic card attempt has FAILED for this period. */
  inDunning: boolean;
  /** Automatic attempts already spent (the expiry-day attempt plus any retries). */
  attemptsMade: number;
  /**
   * Every automatic attempt the ladder will ever make. Zero without a card: the
   * worker makes no attempt at all, so promising four would be a lie.
   */
  attemptsTotal: number;
  /** Attempts still to come. Zero means the final notice has already been sent. */
  attemptsLeft: number;
  /** True once every automatic attempt is spent — suspension is the next event. */
  exhausted: boolean;
  /** When the worker will next try the card. Null when nothing is scheduled. */
  nextAttemptAt: Date | null;
  /**
   * When the server pauses if nothing is paid — the same expression `suspendDueAt`
   * evaluates, including the promise-keeping slip and its cap. Null when the admin
   * kill switch has auto-suspend off, in which case nothing pauses on a timer.
   */
  suspendAt: Date | null;
  /** Whole days since the term ran out. Negative before expiry. */
  daysPastExpiry: number;
};

/**
 * Days past expiry of the plain calendar deadline, before any late-sequence slip.
 * Mirrors `calendarSuspendDay` in worker/billing.ts.
 */
function calendarSuspendDay(graceDays: number, hasCard: boolean): number {
  return hasCard ? Math.max(graceDays, CARD_SUSPEND_DAY) : graceDays;
}

/**
 * Mirrors `suspendDueAt` in worker/billing.ts, including the rule that a suspension
 * never lands before a retry date we have already promised the customer by email —
 * and that the slip that buys is capped, so a Stripe outage cannot defer it forever.
 */
function suspendDueAt(
  server: DunningInput,
  hasCard: boolean,
  cfg: { graceDays: number; autoSuspend: boolean },
): Date | null {
  if (!cfg.autoSuspend || !server.expiresAt) return null;
  const days = calendarSuspendDay(cfg.graceDays, hasCard);
  const at = new Date(server.expiresAt.getTime() + days * DAY);
  if (!hasCard || !server.dunningNextAt || server.dunningNextAt <= at) return at;
  const cap = new Date(server.expiresAt.getTime() + (days + SUSPEND_SLIP_CAP_DAYS) * DAY);
  return server.dunningNextAt < cap ? server.dunningNextAt : cap;
}

/**
 * Turn the raw dunning columns into something a customer can be told without
 * over-promising.
 *
 * Two states the UI must never conflate, which is why they are separate fields:
 * a customer with NO card is not "0 of 4 attempts made" — the worker will never
 * attempt anything for them, and they go to grace and then suspension on the
 * shorter clock. `attemptsTotal` is 0 in that case rather than 4.
 */
export function dunningView(
  server: DunningInput,
  opts: { hasCard: boolean; graceDays: number; autoSuspend: boolean; now: Date },
): DunningView {
  const { hasCard, graceDays, autoSuspend, now } = opts;
  const attemptsMade = hasCard ? Math.min(Math.max(0, server.dunningStage), DUNNING_EXHAUSTED) : 0;
  const attemptsTotal = hasCard ? DUNNING_EXHAUSTED : 0;
  return {
    hasCard,
    inDunning: server.dunningStage > 0,
    attemptsMade,
    attemptsTotal,
    attemptsLeft: Math.max(0, attemptsTotal - attemptsMade),
    exhausted: hasCard && server.dunningStage >= DUNNING_EXHAUSTED,
    nextAttemptAt: hasCard ? server.dunningNextAt : null,
    suspendAt: suspendDueAt(server, hasCard, { graceDays, autoSuspend }),
    daysPastExpiry: server.expiresAt
      ? Math.floor((now.getTime() - server.expiresAt.getTime()) / DAY)
      : 0,
  };
}

