"use client";

/**
 * The customer-facing surface for the saved card that `worker/billing.ts` charges.
 *
 * Everything card-shaped in this app is REDIRECT-based: there is no Stripe.js in
 * the browser and no publishable key is plumbed to it, so a card number is only
 * ever typed on Stripe's own hosted page. Nothing in this file renders, reads or
 * accepts a card number, and nothing in it can — the buttons here only ever send
 * the customer to a URL that Stripe minted.
 *
 * The return leg is the fragile part and is handled by `CardSetupReturn` below.
 */

import { useEffect, useRef, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import {
  finalizeCardSetup,
  removeSavedCard,
  settleOutstanding,
  startCardSetup,
} from "@/lib/actions-payment-method";

/* ------------------------------------------------------------------ *
 * Add a card
 * ------------------------------------------------------------------ */

/**
 * Send the customer to Stripe's hosted setup page.
 *
 * `startCardSetup` returns a URL, so this is a full navigation rather than a
 * fetch — the same shape as `AddFunds`, and the reason no card data ever reaches
 * this origin.
 */
export function AddCardButton({
  label = "Add a card",
  className = "btn-primary",
}: {
  label?: string;
  className?: string;
}) {
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const go = () => {
    setError(null);
    start(async () => {
      const res = await startCardSetup();
      if (res.url) {
        window.location.href = res.url;
        return;
      }
      setError(res.error ?? "We couldn't start card setup. Please try again in a moment.");
    });
  };

  return (
    <div>
      <button className={className} onClick={go} disabled={pending}>
        {pending ? "Redirecting…" : label}
      </button>
      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
    </div>
  );
}

/* ------------------------------------------------------------------ *
 * Remove a card
 * ------------------------------------------------------------------ */

export function RemoveCardButton({ label }: { label: string }) {
  const router = useRouter();
  const [confirming, setConfirming] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const remove = () => {
    setError(null);
    start(async () => {
      const res = await removeSavedCard();
      if (res.error) {
        setError(res.error);
        return;
      }
      setConfirming(false);
      router.refresh();
    });
  };

  if (!confirming) {
    return (
      <div>
        <button className="btn-ghost py-1.5 text-xs" onClick={() => setConfirming(true)}>
          Remove
        </button>
        {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
      </div>
    );
  }

  return (
    <div className="text-right">
      <p className="mb-2 text-xs text-slate-400">
        Remove {label}? Renewals will fall back to your wallet balance alone.
      </p>
      <div className="flex justify-end gap-2">
        <button className="btn-ghost py-1.5 text-xs" onClick={() => setConfirming(false)} disabled={pending}>
          Cancel
        </button>
        <button className="btn-danger py-1.5 text-xs" onClick={remove} disabled={pending}>
          {pending ? "Removing…" : "Yes, remove"}
        </button>
      </div>
      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
    </div>
  );
}

/* ------------------------------------------------------------------ *
 * The return leg from Stripe
 * ------------------------------------------------------------------ */

type FinalizeState =
  | { kind: "working" }
  | { kind: "saved"; label: string }
  | { kind: "failed"; error: string };

/**
 * Completes card setup after Stripe redirects back to
 * `/dashboard/billing?card_setup=<session_id>`.
 *
 * Two things this must not be:
 *  - a silent no-op. Checkout attaches the card at Stripe BEFORE this ever runs,
 *    so a customer who lands here and sees nothing has a card at Stripe and none
 *    on file with us — and would be dunned for it.
 *  - a dead end. If finalising fails, the card may still be saved at Stripe, and
 *    the worker's `adoptUnclaimedCards` backstop claims it on the next sweep. The
 *    failure copy says exactly that, and still offers a retry.
 *
 * `finalizeCardSetup` is documented as safe to call repeatedly with the same
 * session id, so a refreshed tab re-reads the same payment method rather than
 * saving a second card. The ref below is not for correctness, only to stop React's
 * development double-mount from firing two identical round-trips.
 */
export function CardSetupReturn({ sessionId }: { sessionId: string }) {
  const router = useRouter();
  const fired = useRef(false);
  const [state, setState] = useState<FinalizeState>({ kind: "working" });
  const canceled = sessionId === "canceled";

  useEffect(() => {
    if (canceled || fired.current) return;
    fired.current = true;
    void (async () => {
      const res = await finalizeCardSetup(sessionId);
      if (res.ok) {
        setState({ kind: "saved", label: res.label ?? "Card saved" });
        // Drop the one-shot session id from the URL so a refresh or a shared link
        // doesn't replay the return leg, then pull the page's server data again —
        // the action has already revalidated it.
        router.replace("/dashboard/billing");
        router.refresh();
        return;
      }
      setState({ kind: "failed", error: res.error ?? "The card wasn't saved." });
    })();
  }, [sessionId, canceled, router]);

  if (canceled) {
    return (
      <div className="card border-amber-500/30 bg-amber-500/[0.06]">
        <p className="text-sm font-medium text-amber-300">Card setup canceled</p>
        <p className="mt-1 text-sm text-slate-400">
          No card was saved and nothing was charged. Your renewals will keep coming out of your
          wallet balance until a card is on file.
        </p>
        <div className="mt-3">
          <AddCardButton label="Try again" className="btn-secondary py-1.5" />
        </div>
      </div>
    );
  }

  if (state.kind === "working") {
    return (
      <div className="card border-white/[0.08] text-sm text-slate-400">
        Finishing card setup — one moment.
      </div>
    );
  }

  if (state.kind === "saved") {
    return (
      <div className="card border-emerald-500/30 bg-emerald-500/[0.06]">
        <p className="text-sm font-medium text-emerald-300">{state.label} saved</p>
        <p className="mt-1 text-sm text-slate-400">
          Renewals will now charge this card for anything your wallet balance doesn&apos;t cover.
        </p>
      </div>
    );
  }

  return (
    <div className="card border-red-500/30 bg-red-500/[0.06]">
      <p className="text-sm font-medium text-red-300">We couldn&apos;t finish saving your card</p>
      <p className="mt-1 text-sm text-slate-400">{state.error}</p>
      <p className="mt-2 text-xs text-slate-500">
        If you completed the form on Stripe&apos;s page, the card may already be saved on their side
        — we check for that automatically and it will appear here within a few minutes. Nothing was
        charged either way.
      </p>
      <div className="mt-3">
        <AddCardButton label="Try again" className="btn-secondary py-1.5" />
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ *
 * Settle an outstanding balance
 * ------------------------------------------------------------------ */

/**
 * Pay an overdue renewal now, on Stripe's hosted page.
 *
 * The link is minted fresh on every click rather than reusing the stored
 * `dunningPayUrl`, because Checkout sessions expire in 24 hours while the dunning
 * sequence runs for six days — see `settleOutstanding`.
 *
 * `covered: true` is NOT a failure: it means the wallet already funds the renewal
 * and the sweep will apply it. It gets neutral styling, not an error colour.
 */
export function SettleNowButton({
  serverId,
  className = "btn-primary py-1.5 text-xs",
}: {
  serverId: string;
  className?: string;
}) {
  const [message, setMessage] = useState<{ tone: "info" | "error"; text: string } | null>(null);
  const [pending, start] = useTransition();

  const pay = () => {
    setMessage(null);
    start(async () => {
      const res = await settleOutstanding(serverId);
      if (res.url) {
        window.location.href = res.url;
        return;
      }
      setMessage({
        tone: res.covered ? "info" : "error",
        text: res.error ?? "We couldn't start checkout. Please try again in a moment.",
      });
    });
  };

  return (
    <div>
      <button className={className} onClick={pay} disabled={pending}>
        {pending ? "Opening checkout…" : "Pay now"}
      </button>
      {message && (
        <p
          className={`mt-2 text-xs ${
            message.tone === "info" ? "text-slate-400" : "text-red-400"
          }`}
        >
          {message.text}
        </p>
      )}
    </div>
  );
}

