import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { DUNNING_RETRY_ATTEMPTS } from "../lib/mailer.ts";
import {
  CARD_EXPIRY_WARN_DAYS,
  CARD_SUSPEND_DAY,
  DUNNING_EXHAUSTED,
  LAST_RETRY_DAY,
  RETRY_DAYS,
  SUSPEND_SLIP_CAP_DAYS,
  dunningView,
} from "../lib/dunning-schedule.ts";

/**
 * REAL RISK — the portal telling a customer something the worker will not do.
 *
 * `lib/dunning-schedule.ts` exists so the billing page can say where a customer is
 * in the dunning ladder and when their server would pause. It cannot import those
 * numbers from `worker/billing.ts` (that module drags Proxmox, nodemailer and the
 * job queue into a page bundle), so the day arithmetic is duplicated there.
 *
 * A duplicated schedule that drifts is worse than no schedule at all: the page
 * would promise "we'll try again on the 3rd, nothing pauses before the 6th" while
 * the worker suspends on the 4th. This file is the guard — it reads worker/billing.ts
 * and fails the moment the two stop agreeing, exactly as
 * `test/dunning-schedule.test.ts` guards the admin panel's hand-copied floor.
 *
 * Deterministic: source-text assertions and arithmetic on fixed dates. No clock,
 * no DB, no Stripe, no network.
 */

const REPO = join(__dirname, "..");
/** Sources are read with whitespace collapsed, so reformatting is not a failure. */
const readNormalized = (rel: string) => readFileSync(join(REPO, rel), "utf8").replace(/\s+/g, " ");
const BILLING_SRC = readNormalized("worker/billing.ts");
const SCHEDULE_SRC = readNormalized("lib/dunning-schedule.ts");

/* ---- the duplicated arithmetic still matches the worker ------------------ */

test("the portal's retry-day formula is the worker's formula", () => {
  // worker/billing.ts: `const retryDayFor = (retry: number) => 2 * retry - 1;`
  const inWorker = /const retryDayFor = \(retry: number\) => (\d+) \* retry - (\d+);/.exec(BILLING_SRC);
  assert.ok(inWorker, "retryDayFor not found in worker/billing.ts — re-read the ladder");
  const inPortal = /export const retryDayFor = \(retry: number\) => (\d+) \* retry - (\d+);/.exec(SCHEDULE_SRC);
  assert.ok(inPortal, "retryDayFor not found in lib/dunning-schedule.ts");
  assert.equal(inPortal![1], inWorker![1], "retry-day multiplier drifted from the worker");
  assert.equal(inPortal![2], inWorker![2], "retry-day offset drifted from the worker");
});

test("the portal's suspension and slip constants are the worker's", () => {
  const suspendOffset = /const CARD_SUSPEND_DAY = LAST_RETRY_DAY \+ (\d+);/.exec(BILLING_SRC);
  assert.ok(suspendOffset, "CARD_SUSPEND_DAY not found in worker/billing.ts");
  assert.equal(
    CARD_SUSPEND_DAY,
    LAST_RETRY_DAY + Number(suspendOffset![1]),
    "the portal would name a suspension day the worker does not honour",
  );

  const slip = /const SUSPEND_SLIP_CAP_DAYS = (\d+);/.exec(BILLING_SRC);
  assert.ok(slip, "SUSPEND_SLIP_CAP_DAYS not found in worker/billing.ts");
  assert.equal(SUSPEND_SLIP_CAP_DAYS, Number(slip![1]), "the slip cap drifted from the worker");

  const exhausted = /const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS \+ (\d+);/.exec(BILLING_SRC);
  assert.ok(exhausted, "DUNNING_EXHAUSTED not found in worker/billing.ts");
  assert.equal(DUNNING_EXHAUSTED, DUNNING_RETRY_ATTEMPTS + Number(exhausted![1]));

  const warn = /const CARD_EXPIRY_WARN_DAYS = (\d+);/.exec(BILLING_SRC);
  assert.ok(warn, "CARD_EXPIRY_WARN_DAYS not found in worker/billing.ts");
  assert.equal(
    CARD_EXPIRY_WARN_DAYS,
    Number(warn![1]),
    "the page would flag a card as expiring on a different day than the email warns",
  );
});

test("the retry-attempt count is IMPORTED, never re-declared in the portal copy", () => {
  // The one number the dunning emails subtract from. A second copy of it is how
  // "we'll try 2 more times" starts outliving the retries that back it.
  assert.ok(
    SCHEDULE_SRC.includes('import { DUNNING_RETRY_ATTEMPTS } from "./mailer";'),
    "lib/dunning-schedule.ts must import the attempt count, not restate it",
  );
  assert.doesNotMatch(
    SCHEDULE_SRC,
    /const DUNNING_RETRY_ATTEMPTS = \d/,
    "the attempt count must never be hardcoded beside the schedule derived from it",
  );
});

test("the portal's ladder is still the documented day-1/3/5, pause-on-6 schedule", () => {
  assert.deepEqual(RETRY_DAYS, [1, 3, 5]);
  assert.equal(CARD_SUSPEND_DAY, 6);
  assert.equal(DUNNING_EXHAUSTED, 4, "the expiry-day attempt plus three retries");
});

/* ---- the customer-facing view ------------------------------------------- */

const EXPIRY = new Date("2026-07-01T00:00:00.000Z");
const DAY = 86_400_000;
const at = (days: number) => new Date(EXPIRY.getTime() + days * DAY);
const CFG = { graceDays: 3, autoSuspend: true, now: at(2) };

test("no card: the ladder is not promised at all, and grace is the shorter clock", () => {
  const v = dunningView(
    { expiresAt: EXPIRY, dunningStage: 0, dunningNextAt: null },
    { ...CFG, hasCard: false },
  );
  // Promising "0 of 4 attempts" to someone whose card will never be tried is the
  // single most misleading thing this panel could say.
  assert.equal(v.attemptsTotal, 0);
  assert.equal(v.attemptsLeft, 0);
  assert.equal(v.inDunning, false);
  assert.equal(v.nextAttemptAt, null);
  assert.deepEqual(v.suspendAt, at(3), "no card means plain grace, not the card runway");
});

test("card on file, nothing failed yet: the full runway, no decline claimed", () => {
  const v = dunningView(
    { expiresAt: EXPIRY, dunningStage: 0, dunningNextAt: null },
    { ...CFG, hasCard: true },
  );
  assert.equal(v.inDunning, false, "stage 0 means nothing has been declined");
  assert.equal(v.attemptsMade, 0);
  assert.equal(v.attemptsTotal, DUNNING_EXHAUSTED);
  assert.equal(v.attemptsLeft, DUNNING_EXHAUSTED);
  assert.equal(v.exhausted, false);
  assert.deepEqual(v.suspendAt, at(CARD_SUSPEND_DAY), "a card buys the longer runway");
});

test("mid-ladder: attempts made and left add up to what the emails promise", () => {
  for (let stage = 1; stage <= DUNNING_EXHAUSTED; stage++) {
    const v = dunningView(
      { expiresAt: EXPIRY, dunningStage: stage, dunningNextAt: at(1) },
      { ...CFG, hasCard: true },
    );
    assert.equal(v.inDunning, true);
    assert.equal(v.attemptsMade, stage);
    assert.equal(v.attemptsMade + v.attemptsLeft, DUNNING_EXHAUSTED, `stage ${stage}`);
    assert.equal(v.exhausted, stage >= DUNNING_EXHAUSTED, `stage ${stage}`);
  }
});

test("a stage past the end cannot show more attempts than the ladder has", () => {
  // Defensive: a hand-edited row must not render "attempt 9 of 4".
  const v = dunningView(
    { expiresAt: EXPIRY, dunningStage: 99, dunningNextAt: null },
    { ...CFG, hasCard: true },
  );
  assert.equal(v.attemptsMade, DUNNING_EXHAUSTED);
  assert.equal(v.attemptsLeft, 0);
  assert.equal(v.exhausted, true);
});

test("a suspension date never lands before a retry we already promised", () => {
  // A late-starting sequence: the worker has emailed "we'll try again on day 8",
  // so the page must not tell the customer it pauses on day 6.
  const v = dunningView(
    { expiresAt: EXPIRY, dunningStage: 3, dunningNextAt: at(8) },
    { ...CFG, hasCard: true },
  );
  assert.deepEqual(v.suspendAt, at(8));
});

test("…but the slip a promised retry can buy is capped", () => {
  // Otherwise a permanently failing Stripe would have the page promise a
  // suspension date that recedes forever.
  const v = dunningView(
    { expiresAt: EXPIRY, dunningStage: 3, dunningNextAt: at(90) },
    { ...CFG, hasCard: true },
  );
  assert.deepEqual(v.suspendAt, at(CARD_SUSPEND_DAY + SUSPEND_SLIP_CAP_DAYS));
});

test("a retry scheduled before the calendar deadline does not pull suspension in", () => {
  const v = dunningView(
    { expiresAt: EXPIRY, dunningStage: 2, dunningNextAt: at(3) },
    { ...CFG, hasCard: true },
  );
  assert.deepEqual(v.suspendAt, at(CARD_SUSPEND_DAY));
});

test("with auto-suspend off the page must not name a suspension date", () => {
  const v = dunningView(
    { expiresAt: EXPIRY, dunningStage: 2, dunningNextAt: at(3) },
    { ...CFG, hasCard: true, autoSuspend: false },
  );
  assert.equal(v.suspendAt, null, "the admin kill switch means nothing pauses on a timer");
});

test("a long grace period wins over the card runway rather than shortening it", () => {
  // calendarSuspendDay is a max(): an operator who set a 30-day grace must not have
  // it silently cut to the 6-day card ladder.
  const v = dunningView(
    { expiresAt: EXPIRY, dunningStage: 0, dunningNextAt: null },
    { ...CFG, hasCard: true, graceDays: 30 },
  );
  assert.deepEqual(v.suspendAt, at(30));
});

test("days past expiry is whole days, and never invents a date without an expiry", () => {
  const v = dunningView(
    { expiresAt: EXPIRY, dunningStage: 0, dunningNextAt: null },
    { ...CFG, hasCard: true, now: at(5.75) },
  );
  assert.equal(v.daysPastExpiry, 5);

  const none = dunningView(
    { expiresAt: null, dunningStage: 0, dunningNextAt: null },
    { ...CFG, hasCard: true },
  );
  assert.equal(none.suspendAt, null);
  assert.equal(none.daysPastExpiry, 0);
});

