input.content:
/**
 * Throwaway harness: exercises the server-side contract behind the new payment-method
 * UI against the STAGING database and Stripe's TEST mode (sk_test).
 *
 * Nothing here charges a card. `mode: "setup"` sessions carry no amount, and the
 * outstanding-balance session is only MINTED (a link) — money moves only when a human
 * completes Stripe's hosted page, which nothing below does.
 *
 * Everything it creates is deleted at the end.
 */
import { db } from "./lib/db";
import { stripe, stripeConfigured } from "./lib/stripe";
import {
  CARD_SETUP_STARTED,
  adoptUnclaimedCards,
  brandLabel,
  cardDisplayLabel,
  cardExpiresAt,
  createCardSetupSession,
  createOutstandingCheckout,
  detachSavedCard,
  hasChargeableCard,
  saveCardFromSetupSession,
} from "./lib/stripe-cards";

let pass = 0;
let fail = 0;
const ok = (label: string, cond: boolean, detail = "") => {
  if (cond) {
    pass++;
    console.log(`  PASS  ${label}${detail ? ` — ${detail}` : ""}`);
  } else {
    fail++;
    console.log(`  FAIL  ${label}${detail ? ` — ${detail}` : ""}`);
  }
};

async function main() {
  const key = process.env.STRIPE_SECRET_KEY ?? "";
  if (!key.startsWith("sk_test")) throw new Error(`REFUSING TO RUN: not a test key (${key.slice(0, 8)})`);
  console.log(`Stripe configured: ${stripeConfigured()} (key prefix ${key.slice(0, 7)})`);
  console.log(`Database: ${(process.env.DATABASE_URL ?? "").replace(/:\/\/[^@]*@/, "://***@")}\n`);

  const stamp = Date.now();
  const user = await db.user.create({
    data: { email: `cardtest-${stamp}@nxeon.invalid`, name: "Card Harness", passwordHash: "x" },
  });
  const other = await db.user.create({
    data: { email: `cardtest-other-${stamp}@nxeon.invalid`, name: "Other", passwordHash: "x" },
  });
  let customerId: string | null = null;

  try {
    /* 1 — startCardSetup's engine: the hosted setup session ------------------ */
    console.log("1. createCardSetupSession (what startCardSetup returns a URL from)");
    const url = await createCardSetupSession(user);
    ok("returns a Stripe-hosted URL", !!url && url.startsWith("https://checkout.stripe.com/"), url?.slice(0, 46));

    const fresh = await db.user.findUnique({ where: { id: user.id } });
    customerId = fresh!.stripeCustomerId;
    ok("stripeCustomerId persisted by ensureStripeCustomer", !!customerId, customerId ?? "");

    const sessions = await stripe().checkout.sessions.list({ customer: customerId!, limit: 1 });
    const session = sessions.data[0];
    ok("session mode is setup (carries no amount, so no charge is possible)", session.mode === "setup");
    ok("session is tagged with our user id", session.metadata?.nxeonUserId === user.id);
    ok(
      "success_url is the return leg the UI handles",
      !!session.success_url?.includes("/dashboard/billing?card_setup={CHECKOUT_SESSION_ID}"),
      session.success_url ?? "",
    );
    ok(
      "cancel_url is the canceled branch the UI handles",
      !!session.cancel_url?.endsWith("/dashboard/billing?card_setup=canceled"),
      session.cancel_url ?? "",
    );
    ok("session starts open, not complete", session.status === "open");

    /* 2 — finalizeCardSetup's engine: the guards ----------------------------- */
    console.log("\n2. saveCardFromSetupSession (what finalizeCardSetup calls on return)");
    const stolen = await saveCardFromSetupSession(session.id, other.id);
    ok(
      "refuses a session id pasted from another account",
      !!stolen.error && !stolen.card,
      stolen.error ?? "",
    );
    const abandoned = await saveCardFromSetupSession(session.id, user.id);
    ok(
      "refuses an abandoned (never completed) setup — the UI's recoverable branch",
      !!abandoned.error && !abandoned.card,
      abandoned.error ?? "",
    );
    const bogus = await saveCardFromSetupSession("cs_test_does_not_exist", user.id);
    ok("survives a garbage session id without throwing", !!bogus.error, bogus.error ?? "");

    /* 3 — a saved card, as the UI will render it ----------------------------- */
    console.log("\n3. A card on file (attached via Stripe's test token, never a real PAN)");
    const pm = await stripe().paymentMethods.attach("pm_card_visa", { customer: customerId! });
    await db.user.update({
      where: { id: user.id },
      data: {
        stripePaymentMethodId: pm.id,
        cardBrand: pm.card?.brand ?? null,
        cardLast4: pm.card?.last4 ?? null,
        cardExpMonth: pm.card?.exp_month ?? null,
        cardExpYear: pm.card?.exp_year ?? null,
      },
    });
    const withCard = (await db.user.findUnique({ where: { id: user.id } }))!;
    ok("hasChargeableCard is true", hasChargeableCard(withCard));
    const label = cardDisplayLabel({
      brand: withCard.cardBrand,
      last4: withCard.cardLast4,
      expMonth: withCard.cardExpMonth,
      expYear: withCard.cardExpYear,
    });
    ok("renders a display label with no PAN", !!label && !/\d{7,}/.test(label), label ?? "");
    ok("brandLabel humanises the slug", brandLabel(withCard.cardBrand) === "Visa", brandLabel(withCard.cardBrand));
    const exp = cardExpiresAt(withCard.cardExpMonth!, withCard.cardExpYear!);
    ok(
      "cardExpiresAt is the first instant AFTER the expiry month",
      exp.getUTCDate() === 1 && exp.getUTCMonth() === withCard.cardExpMonth! % 12,
      exp.toISOString(),
    );

    /* 4 — settleOutstanding's engine ---------------------------------------- */
    console.log("\n4. createOutstandingCheckout (what settleOutstanding returns a URL from)");
    const payUrl = await createOutstandingCheckout({
      user: withCard,
      amountCents: 1299,
      hostname: "harness-01",
      serverId: "harness-server",
    });
    ok("mints a hosted payment link", !!payUrl && payUrl.startsWith("https://checkout.stripe.com/"), payUrl?.slice(0, 46));
    const paySessions = await stripe().checkout.sessions.list({ customer: customerId!, limit: 2 });
    const pay = paySessions.data.find((s) => s.mode === "payment")!;
    ok("quotes the exact amount asked for", pay.amount_total === 1299, String(pay.amount_total));
    ok("is UNPAID — minting a link moves no money", pay.payment_status === "unpaid", pay.payment_status);
    ok(
      "carries only nxeonUserId, so the shared fulfil path treats it as wallet credit",
      pay.metadata?.nxeonUserId === user.id && !pay.metadata?.nxeonServerId,
      JSON.stringify(pay.metadata),
    );

    /* 5 — the adoption backstop the failure copy promises -------------------- */
    console.log("\n5. adoptUnclaimedCards (the backstop the 'setup failed' copy points at)");
    await db.user.update({ where: { id: user.id }, data: { stripePaymentMethodId: null } });
    await adoptUnclaimedCards();
    const notAdopted = await db.user.findUnique({ where: { id: user.id } });
    ok(
      "does NOT adopt without a card.setup_started audit row",
      notAdopted!.stripePaymentMethodId === null,
    );
    await db.auditLog.create({ data: { userId: user.id, action: CARD_SETUP_STARTED } });
    await adoptUnclaimedCards();
    const adopted = await db.user.findUnique({ where: { id: user.id } });
    ok(
      "DOES adopt a card stranded at Stripe once intent is on record",
      adopted!.stripePaymentMethodId === pm.id,
      adopted!.stripePaymentMethodId ?? "null",
    );

    /* 6 — removeSavedCard's engine ------------------------------------------ */
    console.log("\n6. detachSavedCard (what removeSavedCard calls)");
    const removed = await detachSavedCard(user.id);
    ok("reports success", removed.ok === true && !removed.error, removed.error ?? "");
    const cleared = await db.user.findUnique({ where: { id: user.id } });
    ok(
      "clears every mirrored column",
      cleared!.stripePaymentMethodId === null &&
        cleared!.cardBrand === null &&
        cleared!.cardLast4 === null &&
        cleared!.cardExpMonth === null &&
        cleared!.cardExpYear === null,
    );
    const detachedAtStripe = await stripe().paymentMethods.retrieve(pm.id);
    ok("the method is really detached at Stripe, not just locally", detachedAtStripe.customer === null);
    ok("removing again is idempotent", (await detachSavedCard(user.id)).ok === true);
  } finally {
    console.log("\nCleanup");
    await db.auditLog.deleteMany({ where: { userId: { in: [user.id, other.id] } } });
    await db.user.deleteMany({ where: { id: { in: [user.id, other.id] } } });
